def factor_info_get(factor_id, factor_type):
    factor_type = str(factor_type)
    user_path = os.path.join(backtest_path, 'hg', 'factor')
    if not os.path.exists(user_path):
        return []
    else:
        user_dir_path = os.path.join(user_path, factor_id)
        if not os.path.exists(user_dir_path):
            return []
        elif factor_type == '':
            return []
        elif factor_type == '0':
            info = factor_info_get_model(user_dir_path)
            return info
        elif factor_type == '1':
            info = factor_info_get_strategy(factor_id)
            return info
        elif factor_type == '2':
            info = factor_info_get_risk(user_dir_path)
            return info
        elif factor_type == '3':
            info = factor_info_get_entrust(user_dir_path)
            return info
        else:
            return []
def factor_info_get_model(user_dir_path):
    filelist = os.listdir(user_dir_path)
    if len(filelist) == 0:
        return []
    else:
        model_id_list = []
        for filename in filelist:
            filepath = os.path.join(user_dir_path, filename)
            if os.path.isfile(filepath) and filename.startswith('model_') and filename.endswith('.csv'):
                model_id_pre = filename.split('_')[-1]
                model_id_lst = model_id_pre.split('.')[0]
                model_id_list.append(model_id_lst)
        if len(model_id_list) == 0:
            return []
        else:
            response = []
            for model_id in model_id_list:
                data = {'model_id': model_id}
                filename = 'model_' + model_id + '.csv'
                filepath = os.path.join(user_dir_path, filename)
                with open(filepath, 'r') as fp:
                    csv_reader = csv.reader(fp)
                    for column, value in csv_reader:
                        if column in FACTORCOLUMNS:
                            data[column] = value
                response.append(data)
            else:
                return response
def factor_info_get_strategy(factor_id):
    data = {}
    response = []
    factor_path = os.path.join(backtest_path, 'hg', 'factor')
    factor_info_path = os.path.join(factor_path, FACTOR_INFO_LIST_FILE)
    with FileLock(factor_info_path, mode='shared'):
        df = FileIO(factor_info_path).read(return_type='dataframe', index_col=0)
    if factor_id in df.index:
        data['factor_name'] = df['factor_name'][factor_id]
    user_dir_path = os.path.join(factor_path, factor_id)
    filelist = os.listdir(user_dir_path)
    if len(filelist) == 0:
        return response
    else:
        strategy_factor_filepath = os.path.join(user_dir_path, 'strategy_factor.csv')
        if not os.path.exists(strategy_factor_filepath):
            return response
        else:
            with open(strategy_factor_filepath, 'r') as fp:
                csv_reader = csv.reader(fp)
                for column, value in csv_reader:
                    if not column in STRATEGYFACTOR:
                        if not ['pe_times', 'pb_times', 'total_value']:
                            continue
                    data[column] = value
                else:
                    response.append(data)
            return response
