def write_file(file_path, content, append=False):
    if append is False:
        user_dir_path = os.path.join(notebook_path, '.user_file')
        if not os.path.exists(user_dir_path):
            os.makedirs(user_dir_path)
        if '/' in file_path:
            dir_path = os.path.join(user_dir_path, os.path.split(file_path)[0])
            if not os.path.exists(dir_path):
                os.makedirs(dir_path)
        filepath = os.path.join(user_dir_path, file_path)
        content.to_csv(filepath, encoding='utf-8', index=False)
        system_log.debug('写入文件成功')
        result = 0
        return result
    else:
        user_file_path = os.path.join(notebook_path, '.user_file')
        if not os.path.exists(user_file_path):
            os.makedirs(user_file_path)
        filepath = os.path.join(user_file_path, file_path)
        if not os.path.exists(filepath):
            content.to_csv(filepath, encoding='utf-8', index=False)
            system_log.debug('写入文件成功')
            result = 0
            return result
        else:
            df = pd.read_csv(filepath, encoding='utf-8', dtype=str)
            df.set_index('block_code', inplace=True)
            content.set_index('block_code', inplace=True)
            values = {'model_id': '0', 'is_delete': '1'}
            df = df.append(content).drop_duplicates(['stock_code', 'create_time']).fillna(value=values).reset_index()
            content.reset_index(inplace=True)
            if len(content) > 0:
                from fly.common.tradingday_calendar import get_trading_day
                df_current = df[df['create_time'] == get_trading_day(-1).strftime('%Y%m%d')]
                for i in df_current.index:
                    for j in content.index:
                        if df['stock_code'][i] == content['stock_code'][j] and df['model_id'][i] != content['model_id'][j]:
                            df.loc[i, 'model_id'] = content['model_id'][j]
            df.to_csv(filepath, encoding='utf-8', index=False)
            system_log.debug('写入文件成功')
            result = 0
            return result
def read_file(file_path):
    filepath = os.path.join(notebook_path, '.user_file', file_path)
    if not os.path.exists(filepath):
        system_log.debug('文件缺失，无法读取')
        result = -1
        return result
    else:
        df = pd.read_csv(filepath, encoding='utf-8', dtype=str)
        system_log.debug('读取文件成功')
        return df
