def read_order_csv():
    try:
        trade_id = engine_instance().algo.trade_id
        file_path = os.path.join(base_path, 'result', trade_id, 'sim_order.csv')
        if os.path.exists(file_path):
            df = pd.read_csv(file_path, encoding='utf-8')
            from fly.common.tradingday_calendar import get_trading_day
            df = df[df['orderTime'] > get_trading_day(-1).strftime('%Y-%m-%d 15:00:00')]
            return df
        else:
            return pd.DataFrame()
    except RuntimeError:
        system_log.warning('用户委托表读取失败: %s' % get_traceback_message())
        return pd.DataFrame()
